/bin/bash -lc "sed -n '1,220p' .agents/skills/obelisk/references/retrieval-semantics.md && printf '\\n--- obelisk overview ---\\n' && obelisk --query /dev/stdin <<'EOF'
const map = overview({ limit: 6 });
return { orientation: map.current_project, current: map.current, recent: map.recent_sessions, memories: map.memories };
EOF"

/bin/bash -lc "obelisk --query /dev/stdin <<'EOF'
const queries = [
  ['toggl entry bill', 'exact command terms'],
  ['billable time', 'billing rule'],
  ['tracked time', 'conversion behavior'],
  ['rounding', 'rounding details']
];
const out = {};
for (const [q, facet] of queries) {
  const hits = search(q, { limit: 12 });
  out[facet] = hits.map(h => ({
    uuid: h.message.uuid,
    session: h.session.id,
    timestamp: h.message.timestamp,
    role: h.message.role,
    content_type: h.message.content_type,
    is_meta: h.message.is_meta,
    text: (h.message.text || '').slice(0, 900)
  }));
}
return out;
EOF"

