/bin/bash -lc "obelisk --query /dev/stdin <<'EOF'
const qs = ['entry', 'bill', 'invoice', 'Toggl'];
const out = {};
for (const q of qs) {
  out[q] = search(q, { limit: 20 }).map(h => ({
    uuid: h.message.uuid, session: h.session.id, timestamp: h.message.timestamp,
    role: h.message.role, content_type: h.message.content_type,
    text: (h.message.text || '').slice(0, 700)
  }));
}
return out;
EOF"
